package main
import("encoding/csv";"encoding/json";"fmt";"html/template";"log";"net/http";"os";"strings";"sync";"time";mail "github.com/xhit/go-simple-mail/v2")
type SMTP struct{Host,Username,Password,FromName,FromEmail,Encryption string;Port int};type Contact struct{Name string `json:"name"`;Email string `json:"email"`;Consented bool `json:"consented"`};type Campaign struct{Name,Subject,Status string;Recipients,Sent,Failed int;CreatedAt string};type Store struct{Contacts []Contact `json:"contacts"`;Campaigns []Campaign `json:"campaigns"`};var mu sync.Mutex;var db Store
func file()string{if x:=os.Getenv("DATA_FILE");x!=""{return x};return "data/store.json"};func load(){b,e:=os.ReadFile(file());if e==nil{_=json.Unmarshal(b,&db)}};func save(){b,_:=json.MarshalIndent(db,"","  ");_=os.WriteFile(file(),b,0600)};func out(w http.ResponseWriter,v any){w.Header().Set("Content-Type","application/json");_=json.NewEncoder(w).Encode(v)}
func cfg()SMTP{p:=587;return SMTP{os.Getenv("SMTP_HOST"),os.Getenv("SMTP_USERNAME"),os.Getenv("SMTP_PASSWORD"),os.Getenv("FROM_NAME"),os.Getenv("FROM_EMAIL"),env("SMTP_ENCRYPTION","STARTTLS"),p}}
func env(k,d string)string{if v:=os.Getenv(k);v!=""{return v};return d};func auth(next http.HandlerFunc)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){u,p,ok:=r.BasicAuth();if !ok||u!=os.Getenv("ADMIN_USER")||p!=os.Getenv("ADMIN_PASSWORD"){w.Header().Set("WWW-Authenticate",`Basic realm="Simple Mail"`);http.Error(w,"Authentication required",401);return};next(w,r)}}
func state(w http.ResponseWriter,r *http.Request){mu.Lock();defer mu.Unlock();out(w,db)}
func contacts(w http.ResponseWriter,r *http.Request){f,_,e:=r.FormFile("file");if e!=nil{http.Error(w,"CSV required",400);return};defer f.Close();rows,e:=csv.NewReader(f).ReadAll();if e!=nil||len(rows)<2{http.Error(w,"invalid CSV",400);return};h:=map[string]int{};for i,x:=range rows[0]{h[strings.ToLower(strings.TrimSpace(x))]=i};ei,ok:=h["email"];if !ok{http.Error(w,"email column required",400);return};ni:=h["name"];ci,cok:=h["consented"];n:=0;mu.Lock();defer mu.Unlock();for _,row:=range rows[1:]{if ei>=len(row){continue};em:=strings.TrimSpace(row[ei]);if !strings.Contains(em,"@"){continue};name:="";if ni<len(row){name=row[ni]};cons:=false;if cok&&ci<len(row){v:=strings.ToLower(strings.TrimSpace(row[ci]));cons=v=="true"||v=="yes"||v=="1"};if cons{db.Contacts=append(db.Contacts,Contact{name,em,true});n++}};save();out(w,map[string]any{"added":n})}
func conn(s SMTP)(*mail.SMTPClient,error){x:=mail.NewSMTPClient();x.Host=s.Host;x.Port=s.Port;x.Username=s.Username;x.Password=s.Password;x.KeepAlive=true;x.ConnectTimeout=10*time.Second;x.SendTimeout=20*time.Second;if s.Encryption=="SSL"{x.Encryption=mail.EncryptionSSL}else if s.Encryption=="None"{x.Encryption=mail.EncryptionNone}else{x.Encryption=mail.EncryptionSTARTTLS};return x.Connect()}
func test(w http.ResponseWriter,r *http.Request){var q struct{To string `json:"to"`};_=json.NewDecoder(r.Body).Decode(&q);s:=cfg();c,e:=conn(s);if e!=nil{http.Error(w,e.Error(),500);return};defer c.Close();m:=mail.NewMSG();m.SetFrom(fmt.Sprintf("%s <%s>",s.FromName,s.FromEmail)).AddTo(q.To).SetSubject("SMTP test").SetBody(mail.TextHTML,"<p>SMTP test successful.</p>");if e=m.Send(c);e!=nil{http.Error(w,e.Error(),500);return};out(w,map[string]bool{"ok":true})}
func send(w http.ResponseWriter,r *http.Request){var q struct{Name,Subject,Body string;ConfirmConsent bool};if json.NewDecoder(r.Body).Decode(&q)!=nil||q.Subject==""||q.Body==""||!q.ConfirmConsent{http.Error(w,"subject, body and consent confirmation required",400);return};mu.Lock();list:=append([]Contact(nil),db.Contacts...);mu.Unlock();if len(list)==0||len(list)>500{http.Error(w,"recipient count must be 1-500",400);return};s:=cfg();c,e:=conn(s);if e!=nil{http.Error(w,e.Error(),500);return};defer c.Close();sent,failed:=0,0;for _,p:=range list{body:=strings.ReplaceAll(q.Body,"{{name}}",template.HTMLEscapeString(p.Name));body+=`<hr><small>You received this because you opted in. Contact the sender to unsubscribe.</small>`;m:=mail.NewMSG();m.SetFrom(fmt.Sprintf("%s <%s>",s.FromName,s.FromEmail)).AddTo(p.Email).SetSubject(q.Subject).SetBody(mail.TextHTML,body);if m.Send(c)!=nil{failed++}else{sent++}};status:="Completed";if failed>0{status="Partial"};mu.Lock();db.Campaigns=append([]Campaign{{q.Name,q.Subject,status,len(list),sent,failed,time.Now().Format(time.RFC3339)}},db.Campaigns...);save();mu.Unlock();out(w,map[string]any{"sent":sent,"failed":failed})}
func main(){load();http.Handle("/static/",http.StripPrefix("/static/",http.FileServer(http.Dir("static"))));http.HandleFunc("/healthz",func(w http.ResponseWriter,r *http.Request){w.WriteHeader(200);_,_=w.Write([]byte("ok"))});http.HandleFunc("/api/state",auth(state));http.HandleFunc("/api/contacts",auth(contacts));http.HandleFunc("/api/test",auth(test));http.HandleFunc("/api/send",auth(send));http.HandleFunc("/",auth(func(w http.ResponseWriter,r *http.Request){http.ServeFile(w,r,"static/index.html")}));port:=env("PORT","10000");log.Fatal(http.ListenAndServe(":"+port,nil))}
